const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元一次方程解题流程卡' },
      { kind: 'text', payload: '原方程：7x+-3=1x+4' },
      { kind: 'text', payload: '① 移项' },
      { kind: 'text', payload: '7x - 1x = 4 + 3' },
      { kind: 'text', payload: '② 合并同类项' },
      { kind: 'text', payload: '6x = 7' },
      { kind: 'text', payload: '③ 系数化为 1' },
      { kind: 'text', payload: 'x = 7/6' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(22, W * 0.055);
    var gap = Math.max(16, W * 0.028);
    var titleY = Math.max(22, H * 0.08);
    var eqY = Math.max(titleY + 34, H * 0.19);
    var panelY = Math.max(eqY + 40, H * 0.31);
    var panelH = Math.max(120, H - panelY - Math.max(28, H * 0.08));
    var panelW = (W - 2 * margin - 2 * gap) / 3;
    var accentH = 8;
    var panelFill = '#F2F7FD';
    var panelAccent = ['#3B82F6', '#10B981', '#F59E0B'];
    var textColor = '#1F2A44';
    var muted = '#44546A';
    var arrowColor = '#8FA6C4';
    function rect(x, y, w, h) {
      return [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']];
    }
    function arrowShape(x1, y, x2) {
      var head = Math.min(10, Math.max(6, (x2 - x1) * 0.35));
      var shaft = 2;
      return [['M', x1, y - shaft], ['L', x2 - head, y - shaft], ['L', x2 - head, y - head * 0.55], ['L', x2, y], ['L', x2 - head, y + head * 0.55], ['L', x2 - head, y + shaft], ['L', x1, y + shaft], ['Z']];
    }
    var paths = [];
    var nodes = [];
    var centers = [];
    var i;
    for (i = 0; i < 3; i++) {
      var x = margin + i * (panelW + gap);
      var pid = 'panel-' + i;
      paths.push({ id: pid, commands: rect(x, panelY, panelW, panelH) });
      nodes.push({ type: 'path', pathId: pid, fill: panelFill });
      var aid = 'accent-' + i;
      paths.push({ id: aid, commands: rect(x, panelY, panelW, accentH) });
      nodes.push({ type: 'path', pathId: aid, fill: panelAccent[i] });
      centers.push(x + panelW / 2);
    }
    for (i = 0; i < 2; i++) {
      var ax1 = margin + (i + 1) * panelW + i * gap + 4;
      var ax2 = ax1 + gap - 8;
      var ay = panelY + panelH / 2;
      var arrid = 'arrow-' + i;
      paths.push({ id: arrid, commands: arrowShape(ax1, ay, ax2) });
      nodes.push({ type: 'path', pathId: arrid, fill: arrowColor });
    }
    nodes.push({ type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: titleY }, hAlign: 'center', vAlign: 'middle', color: textColor });
    nodes.push({ type: 'label', contentId: metrics[1].contentId, anchor: { x: W / 2, y: eqY }, hAlign: 'center', vAlign: 'middle', color: muted });
    for (i = 0; i < 3; i++) {
      var cx = centers[i];
      var titleLineY = panelY + accentH + Math.max(34, panelH * 0.25);
      var eqLineY = panelY + accentH + Math.max(86, panelH * 0.62);
      nodes.push({ type: 'label', contentId: metrics[2 + i * 2].contentId, anchor: { x: cx, y: titleLineY }, hAlign: 'center', vAlign: 'middle', color: textColor });
      nodes.push({ type: 'label', contentId: metrics[3 + i * 2].contentId, anchor: { x: cx, y: eqLineY }, hAlign: 'center', vAlign: 'middle', color: textColor });
    }
    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
